static void patchMajorVersion(Path classFile, int newMajor) throws IOException {
    byte[] bytes = Files.readAllBytes(classFile);
    bytes[6] = (byte) ((newMajor >> 8) & 0xFF);
    bytes[7] = (byte) (newMajor & 0xFF);
    Files.write(classFile, bytes);
}
