static List<String> generateTroubleshootingChecklist(String errorType) {
    return switch (errorType) {
        case "ClassNotFoundException" -> List.of("Sprawdz classpath", "Sprawdz literowke w nazwie klasy");
        case "NoClassDefFoundError" -> List.of("Sprawdz czy JAR jest na runtime classpath", "Sprawdz czy nie usunieto zaleznosci");
        case "NoSuchMethodError" -> List.of("Sprawdz zgodnosc wersji bibliotek", "Przekompiluj cala aplikacje");
        case "UnsupportedClassVersionError" -> List.of("Sprawdz wersje JDK build vs runtime", "Zaktualizuj JRE albo zmien target Javy");
        default -> List.of();
    };
}
for (String e : List.of("ClassNotFoundException","NoClassDefFoundError","NoSuchMethodError","UnsupportedClassVersionError"))
    System.out.println(e + ": " + generateTroubleshootingChecklist(e));

