static void analyzeRootCause(Throwable t) {
    Throwable current = t;
    int level = 0;
    while (current != null) {
        System.out.println("  ".repeat(level) + current.getClass().getName() + ": " + current.getMessage());
        current = current.getCause();
        level++;
    }
}

