static boolean isValidClassFile(Path classFile) throws IOException {
    byte[] b = Files.readAllBytes(classFile);
    boolean magicOk = (b[0]&0xFF)==0xCA && (b[1]&0xFF)==0xFE && (b[2]&0xFF)==0xBA && (b[3]&0xFF)==0xBE;
    int major = ((b[6] & 0xFF) << 8) | (b[7] & 0xFF);
    return magicOk && major >= 45 && major <= 70;
}

static void runPipeline(int failAtStep) {
    String[] steps = {"kompilacja","testy","pakowanie","publikacja","powiadomienie"};
    List<String> log = new ArrayList<>();
    for (int i = 0; i < steps.length; i++) {
        if (i == failAtStep) { System.out.println("BLAD na kroku: " + steps[i]); System.out.println("Log: " + log); return; }
        log.add(steps[i] + " OK");
    }
    System.out.println("Wszystkie kroki OK: " + log);
}
runPipeline(2);

static String diagnose(boolean atCompileTime, boolean workedBeforeNotNow, boolean differentJdkVersion) {
    if (differentJdkVersion) return "UnsupportedClassVersionError";
    if (atCompileTime) return "ClassNotFoundException (brak klasy przy jawnym wczytaniu)";
    if (workedBeforeNotNow) return "NoSuchMethodError (niezgodnosc wersji biblioteki)";
    return "NoClassDefFoundError (brak klasy w runtime)";
}
System.out.println(diagnose(true, false, false));

